function table(items,actions=false){return '<div class="calc-table-scroll"><table class="calc-output-table segment-table"><thead><tr>'+[['name',L('Tên đoạn','Segment')],['flow','Q (m³/h)'],['size',L('Kích thước trong (mm)','Internal size (mm)')],['velocity','v (m/s)'],['friction',L('Suất tổn thất / độ đầy','Friction loss rate / depth ratio')],['length','L (m)'],['pass',L('Đạt tiêu chí','Within limits')]].map(([k,t])=>'<th'+(actions?' aria-sort="'+(sort===k?(dir===1?'ascending':'descending'):'none')+'"':'')+'>'+(actions?'<button type="button" data-segment-sort="'+k+'">'+t+' '+(sort===k?(dir===1?'↑':'↓'):'↕')+'</button>':t)+'</th>').join('')+(actions?'<th>'+L('Thao tác','Actions')+'</th>':'')+'</tr></thead><tbody>'+ordered(items).map(v=>'<tr><td><strong>'+E(v.name)+'</strong><br><small>'+E(v.tool==='duct'?(v.kind==='rect'?L('Chữ nhật','Rectangular'):L('Tròn','Round')):v.kind==='gravity'?L('Thoát nước tự chảy','Gravity drainage'):L('Ống nước có áp','Pressure pipe'))+'</small></td><td>'+F(v.flow)+'</td><td>'+(v.kind==='rect'?F(v.a,1)+' × '+F(v.b,1):'Ø '+F(v.a,1))+'</td><td>'+F(v.velocity)+'</td><td>'+(v.kind==='gravity'?F(v.fill*100,1)+'%':F(v.friction)+' Pa/m')+'</td><td>'+(v.kind==='gravity'?'—':F(v.length))+'</td><td class="'+(pass(v)?'segment-pass':'segment-fail')+'">'+L(pass(v)?'✓ Đạt':'✕ Không đạt',pass(v)?'✓ Pass':'✕ Fail')+'</td>'+(actions?'<td><button type="button" data-segment-edit="'+E(v.id)+'">'+L('Sửa','Edit')+'</button> <button type="button" data-segment-delete="'+E(v.id)+'">'+L('Xóa','Delete')+'</button></td>':'')+'</tr>').join('')+'</tbody></table></div>';}
function report(p){return ['duct','water'].map(k=>{const items=p?.segmentLists?.[k];if(!valid(items)||!items.length)return '';return '<section class="project-report-tool"><h2>'+L(k==='duct'?'Danh sách đoạn ống gió':'Danh sách đoạn ống nước',k==='duct'?'Air duct schedule':'Water pipe schedule')+'</h2>'+table(items)+'<h3>'+L('Điều kiện tính đã lưu','Saved design conditions')+'</h3>'+items.map(v=>'<p><strong>'+E(v.name)+'</strong> · '+L('Lưu lúc','Saved')+': '+E(new Date(v.date).toLocaleString(en?'en-GB':'vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}))+'<br>'+ (v.kind==='gravity'?L('Độ dốc','Slope')+': '+F(v.slope*100)+'% · n = '+F(v.n,4)+' · '+L('Độ đầy tối đa','Maximum depth ratio')+': '+F(v.maxFill*100)+'% · v: '+F(v.vmin)+'–'+F(v.vmax)+' m/s':L('Vận tốc tối đa','Maximum velocity')+': '+F(v.vmax)+' m/s · '+L('Suất tổn thất ma sát tối đa','Maximum friction')+': '+F(v.pmax)+' Pa/m · '+L('Nhiệt độ','Temperature')+': '+F(v.temp)+' °C · ε: '+F(v.rough,3)+' mm')+' · '+L('Vật liệu','Material')+': '+E(material(v))+' · UTC+7</p>').join('')+'<p>'+L('Đạt chỉ xác nhận các giới hạn vận tốc, ma sát (hoặc năng lực thoát và độ đầy với ống tự chảy), cùng tỷ lệ cạnh ≤ 4 cho ống gió. Đây là các đoạn riêng lẻ, chưa xác nhận tổng tổn thất tuyến hay chọn quạt/bơm.','Pass confirms velocity and friction limits (or drainage capacity and depth for gravity pipes), plus duct aspect ratio ≤ 4. These are individual segments; the schedule does not establish total path losses or fan/pump selection.')+'</p></section>';}).join('');}
window.HVACSegments={valid,pass,report};
if(!['duct','water'].includes(key))return;
const section=document.createElement('section');section.className='panel segment-list';section.innerHTML='<div class="panel-title"><h2>'+L('Danh sách đoạn ống đã lưu','Saved pipe / duct segments')+'</h2><div class="report-buttons"><button type="button" data-segment-preview>'+L('Xem báo cáo','View report')+'</button><button type="button" data-segment-print>'+L('Xuất PDF','Export PDF')+'</button></div></div><p class="field-help">'+L('Lưu từng đoạn đạt yêu cầu vào dự án. Kết quả giữ nguyên tại thời điểm thêm; sửa đoạn để tính và cập nhật lại. Tối đa 300 đoạn mỗi công cụ.','Save qualifying segments to your project. Results stay as saved; edit a segment to recalculate and update it. Up to 300 segments per tool.')+'</p><div class="segment-editor"><label>'+L('Tên đoạn','Segment name')+'<input data-segment-name maxlength="100" placeholder="'+(key==='duct'?'SA-01':'CHWS-01')+'"></label><button type="button" data-segment-add>'+L('Thêm vào danh sách','Add to schedule')+'</button><button type="button" data-segment-cancel hidden>'+L('Hủy sửa','Cancel edit')+'</button></div><p class="field-help" data-segment-message role="status"></p><div data-segment-table></div>';
