if(options)options.insertAdjacentElement('afterend',section);else main.insertBefore(section,main.querySelector('.useful-links')||main.querySelector('footer'));
const wrap=options?.querySelector('.table-wrap'),candidateTable=wrap?.querySelector('table');
if(wrap&&candidateTable){const fitFive=()=>{const visible=[...candidateTable.querySelectorAll('tbody tr')].slice(0,5),last=visible.at(-1);if(!last)return;const height=last.getBoundingClientRect().bottom-candidateTable.getBoundingClientRect().top;const scrollbar=wrap.offsetHeight-wrap.clientHeight;wrap.style.maxHeight=Math.ceil(height+scrollbar)+'px';};new MutationObserver(()=>requestAnimationFrame(fitFive)).observe(candidateTable,{childList:true,subtree:true});new ResizeObserver(fitFive).observe(candidateTable);requestAnimationFrame(fitFive);}

const items=()=>{const a=window.HVACProjects?.current()?.segmentLists?.[key];return valid(a)?a:[];},message=s=>section.querySelector('[data-segment-message]').textContent=s;
function refresh(){section.querySelector('[data-segment-table]').innerHTML=items().length?table(items(),true):'<p class="field-help">'+L('Chưa có đoạn ống nào được lưu.','No saved segments yet.')+'</p>';section.querySelector('[data-segment-add]').textContent=editing?L('Cập nhật đoạn','Update segment'):L('Thêm vào danh sách','Add to schedule');section.querySelector('[data-segment-cancel]').hidden=!editing;for(const b of section.querySelectorAll('[data-segment-preview],[data-segment-print]'))b.disabled=!items().length;}
function current(){let x,r,kind,prefix;if(key==='duct'){if(document.getElementById('error').hidden===false)return null;x=getInput();r=rows[selected??0];kind=shape;prefix='';}else{if(W('error').hidden===false)return null;x=waterInput();r=waterChosen;kind=x.gravity?'gravity':'pressure';prefix='w-';}if(!r)return null;const values={};for(const el of main.querySelectorAll('input[id],select[id]'))if(!el.closest('.project-bar')&&!section.contains(el))values[el.id]=el.value;return {id:editing||crypto.randomUUID(),tool:key,name:section.querySelector('[data-segment-name]').value.trim(),date:new Date().toISOString(),kind,flow:x.q*3600,a:key==='duct'?r.a:r.diameter,b:key==='duct'&&kind==='rect'?r.b:key==='duct'?r.a:r.diameter,velocity:r.V,friction:r.R||0,length:x.l||0,vmax:kind==='gravity'?x.max:x.v,pmax:key==='duct'?x.p:x.r||0,fill:r.fill||0,capacity:r.capacity||0,vmin:x.min||0,slope:x.s||0,maxFill:x.fill||0,n:x.n||0,temp:x.t||0,rough:x.e||0,system:key==='water'?W('system').value:'',material:key==='duct'?String(document.getElementById('material').selectedIndex):W('material').value,values};}
function edit(v){editing=v.id;section.querySelector('[data-segment-name]').value=v.name;if(key==='duct'){document.querySelector('#modes [data-mode="check"]').click();document.querySelector('#shapes [data-shape="'+v.kind+'"]').click();}else document.querySelector('#w-modes [data-mode="check"]').click();for(const [id,value] of Object.entries(v.values)){const el=document.getElementById(id);if(el&&!el.closest('.project-bar')&&!section.contains(el))el.value=value;}if(key==='duct'){document.getElementById('material').selectedIndex=Number(v.material);document.getElementById('width').value=v.a;document.getElementById('height').value=v.b;priorUnit=Number(document.getElementById('unit').value);update();}else{W('diameter').value=v.a;waterUnit=Number(W('unit').value);const g=W('system').value==='drain';W('gravity').hidden=!g;W('pressure').hidden=g;waterUpdate();}message(L('Đã nạp đoạn để kiểm tra. Thay đổi thông số rồi nhấn Cập nhật đoạn.','Segment loaded. Adjust inputs, then select Update segment.'));refresh();main.querySelector('.results')?.scrollIntoView({behavior:'smooth',block:'start'});}
function preview(print=false){const p=window.HVACProjects.current();if(!p||!items().length)return;document.getElementById('segment-report-dialog')?.remove();const d=document.createElement('dialog');d.id='segment-report-dialog';d.className='project-report-dialog';const html=window.HVACProjects.metadata()+report({...p,segmentLists:{[key]:items()}});d.innerHTML='<div class="project-actions"><button data-close>'+L('Đóng','Close')+'</button><button data-print>'+L('Xuất PDF','Export PDF')+'</button></div><article>'+html+'</article>';document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();const run=()=>{document.getElementById('project-print-report')?.remove();const a=document.createElement('article');a.id='project-print-report';a.innerHTML=html;document.body.append(a);window.HVACPrint.run('project');};d.querySelector('[data-print]').onclick=run;if(print)run();else d.showModal();}
section.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-segment-add')){if(!window.HVACProjects.current()){message(L('Hãy chọn hoặc tạo dự án ở phía trên để lưu danh sách.','Select or create a project above to save the schedule.'));document.getElementById('project-select')?.focus();return;}const v=current();if(!v||!v.name||!valid([v])||!pass(v)){message(L('Nhập tên đoạn và chọn kích thước đạt các giới hạn trước khi lưu.','Enter a segment name and select a size within the limits before saving.'));return;}const next=items().filter(i=>i.id!==v.id);next.push(v);if(!window.HVACProjects.saveSegments(key,next)){message(L('Không lưu được. Kiểm tra dung lượng lưu trữ hoặc giới hạn 300 đoạn.','Unable to save. Check storage capacity or the 300-segment limit.'));return;}editing=null;section.querySelector('[data-segment-name]').value='';message(L('Đã lưu đoạn vào dự án.','Segment saved to project.'));refresh();}if(b.hasAttribute('data-segment-cancel')){editing=null;message('');refresh();}if(b.dataset.segmentSort){if(sort===b.dataset.segmentSort)dir*=-1;else{sort=b.dataset.segmentSort;dir=1;}refresh();}if(b.dataset.segmentEdit){const v=items().find(v=>v.id===b.dataset.segmentEdit);if(v)edit(v);}if(b.dataset.segmentDelete){const id=b.dataset.segmentDelete,v=items().find(v=>v.id===id);if(!v)return;const d=document.createElement('dialog');d.className='project-trash-dialog';d.innerHTML='<h2>'+L('Xóa đoạn đã lưu?','Delete saved segment?')+'</h2><p>'+E(v.name)+'</p><div class="project-actions"><button data-cancel>'+L('Hủy','Cancel')+'</button><button data-delete>'+L('Xóa','Delete')+'</button></div>';document.body.append(d);d.querySelector('[data-cancel]').onclick=()=>{d.close();d.remove();};d.querySelector('[data-delete]').onclick=()=>{if(window.HVACProjects.saveSegments(key,items().filter(v=>v.id!==id))){if(editing===id)editing=null;refresh();d.close();d.remove();}else message(L('Không thể lưu thay đổi.','Unable to save changes.'));};d.showModal();}if(b.hasAttribute('data-segment-preview'))preview();if(b.hasAttribute('data-segment-print'))preview(true);});document.addEventListener('hvac-project-ready',refresh);window.addEventListener('storage',()=>setTimeout(refresh,0));refresh();
